            memoText: "Conservation of momentum (system initially at rest): 0 = m_A(−0.4) + m_B × v_B. v_B = 3.2×0.4/2.6 = 0.492 m/s (to right). d = v_B × t = 0.492 × 1.3 = 0.64 m. (5 marks)",
