            memoText: "C will have a SMALLER velocity than B. By conservation of momentum: m_A × v_A = m_C × v_C. If m_C > m_B, then v_C < v_B (since m_A and v_A remain the same). (3 marks)",
            topic: "Momentum and Impulse",
